public class AuthEndpointsTests : IClassFixture<TestWebApplicationFactory<Program>>, IAsyncLifetime
{
    private readonly TestWebApplicationFactory<Program> _factory;
    private IServiceScope _scope;

    public AuthEndpointsTests(TestWebApplicationFactory<Program> factory)
    {
        _factory = factory;
    }

    public async Task InitializeAsync()
    {
        _scope = _factory.Services.CreateScope();
        var context = _scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        await context.Database.BeginTransactionAsync();
    }

    public async Task DisposeAsync()
    {
        var context = _scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        await context.Database.RollbackTransactionAsync();
        _scope.Dispose();
    }
}

