import { useState, useEffect, useCallback } from 'react';
import { Todo, CreateTodoPayload, UpdateTodoPayload } from '../types/todo';
import { getTodos, createTodo, updateTodo, deleteTodo } from '../api/todos';

interface UseTodosResult {
  todos: Todo[];
  loading: boolean;
  error: string | null;
  addTodo: (payload: CreateTodoPayload) => Promise<void>;
  updateTodoItem: (id: string, payload: UpdateTodoPayload) => Promise<void>;
  deleteTodoItem: (id: string) => Promise<void>;
  refreshTodos: () => Promise<void>;
}

export const useTodos = (): UseTodosResult => {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const fetchTodos = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await getTodos();
      setTodos(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchTodos();
  }, [fetchTodos]);

  const addTodo = async (payload: CreateTodoPayload) => {
    try {
      const newTodo = await createTodo(payload);
      setTodos((prevTodos) => [...prevTodos, newTodo]);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to add todo');
      throw err;
    }
  };

  const updateTodoItem = async (id: string, payload: UpdateTodoPayload) => {
    try {
      const updated = await updateTodo(id, payload);
      setTodos((prevTodos) =>
        prevTodos.map((todo) => (todo.id === id ? updated : todo))
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update todo');
      throw err;
    }
  };

  const deleteTodoItem = async (id: string) => {
    try {
      await deleteTodo(id);
      setTodos((prevTodos) => prevTodos.filter((todo) => todo.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to delete todo');
      throw err;
    }
  };

  return {
    todos,
    loading,
    error,
    addTodo,
    updateTodoItem,
    deleteTodoItem,
    refreshTodos: fetchTodos,
  };
};

import React, { useState, useEffect } from 'react';
import { ITodo } from '../types/Todo';
import './TodoForm.css';

interface TodoFormProps {
  initialTodo?: ITodo;
  onSubmit: (todo: Omit<ITodo, 'id'> | Partial<ITodo>) => void;
  onCancel?: () => void;
  isEditMode?: boolean;
}

const TodoForm: React.FC<TodoFormProps> = ({
  initialTodo,
  onSubmit,
  onCancel,
  isEditMode = false,
}) => {
  const [title, setTitle] = useState(initialTodo?.title || '');
  const [description, setDescription] = useState(initialTodo?.description || '');
  const [completed, setCompleted] = useState(initialTodo?.completed || false);

  useEffect(() => {
    if (initialTodo) {
      setTitle(initialTodo.title);
      setDescription(initialTodo.description);
      setCompleted(initialTodo.completed);
    } else {
      setTitle('');
      setDescription('');
      setCompleted(false);
    }
  }, [initialTodo]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) {
      alert('Title cannot be empty.');
      return;
    }
    onSubmit({ title, description, completed });
    if (!isEditMode) {
      setTitle('');
      setDescription('');
      setCompleted(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="todo-form">
      <div className="form-group">
        <label htmlFor="title">Title:</label>
        <input
          type="text"
          id="title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
          className="form-input"
        />
      </div>
      <div className="form-group">
        <label htmlFor="description">Description:</label>
        <textarea
          id="description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          rows={4}
          className="form-textarea"
        ></textarea>
      </div>
      {isEditMode && (
        <div className="form-group checkbox-group">
          <input
            type="checkbox"
            id="completed"
            checked={completed}
            onChange={(e) => setCompleted(e.target.checked)}
            className="form-checkbox"
          />
          <label htmlFor="completed">Completed</label>
        </div>
      )}
      <div className="form-actions">
        <button type="submit" className="button primary-button">
          {isEditMode ? 'Update Todo' : 'Add Todo'}
        </button>
        {onCancel && (
          <button type="button" onClick={onCancel} className="button secondary-button">
            Cancel
          </button>
        )}
      </div>
    </form>
  );
};

export default TodoForm;

