const API_BASE_URL = '/api/v1/todos';

// F-008: Centralized API response handling for better error messages
const handleApiResponse = async (response: Response): Promise<any> => {
  if (response.status === 204) { // No Content
    return null;
  }
  if (!response.ok) {
    const errorBody = await response.json().catch(() => null); // F-008: Try to parse JSON error
    const errorMessage = errorBody?.detail || errorBody?.message || response.statusText;
    throw new Error(`API Error: ${errorMessage}`);
  }
  return response.json();
};

export const getTodos = async (
  completed?: boolean
): Promise<ITodo[]> => {
  const params = new URLSearchParams();
  if (completed !== undefined) {
    params.append('completed', String(completed));
  }
  // F-002: Removed sortBy and sortOrder from params as backend does not utilize them
  const response = await fetch(`${API_BASE_URL}?${params.toString()}`);
  return handleApiResponse(response);
};

export const getTodo = async (id: string): Promise<ITodo> => {
  const response = await fetch(`${API_BASE_URL}/${id}`);
  return handleApiResponse(response);
};

export const createTodo = async (todo: Omit<ITodo, 'id' | 'createdAt' | 'updatedAt'>): Promise<ITodo> => {
  const response = await fetch(API_BASE_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(todo),
  });
  return handleApiResponse(response);
};

export const updateTodo = async (id: string, todo: Partial<Omit<ITodo, 'createdAt' | 'updatedAt'>>): Promise<void> => { // F-005: Changed return type to void
  const response = await fetch(`${API_BASE_URL}/${id}`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(todo),
  });
  await handleApiResponse(response); // F-005: No content expected from backend
};

export const deleteTodo = async (id: string): Promise<void> => {
  const response = await fetch(`${API_BASE_URL}/${id}`, {
    method: 'DELETE',
  });
  await handleApiResponse(response); // F-005: No content expected from backend
};

import React, { useEffect, useState, useCallback } from 'react';
import AddTodoForm from '../components/AddTodoForm';
import TodoList from '../components/TodoList';
import { Todo } from '../types/todo';
import { getTodos, createTodo, completeTodo } from '../api/todos';
import './HomePage.css';

const HomePage: React.FC = () => {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchTodos = useCallback(async () => {
    try {
      setLoading(true);
      const data = await getTodos();
      setTodos(data);
    } catch (err) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred while fetching todos.');
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchTodos();
  }, [fetchTodos]);

  const handleAddTodo = async (title: string) => {
    try {
      const newTodo = await createTodo(title);
      setTodos((prevTodos) => [...prevTodos, newTodo]);
    } catch (err) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred while adding a todo.');
      }
    }
  };

  const handleToggleComplete = async (id: string) => {
    try {
      const updatedTodo = await completeTodo(id);
      setTodos((prevTodos) =>
        prevTodos.map((todo) => (todo.id === id ? updatedTodo : todo))
      );
    } catch (err) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred while completing a todo.');
      }
    }
  };

  if (loading) {
    return <div className="homepage-container">Loading todos...</div>;
  }

  if (error) {
    console.error("Detailed error:", error); // Log the actual error for debugging
    return <div className="homepage-container error-message">An unexpected error occurred. Please try again later.</div>;
  }

  return (
    <div className="homepage-container">
      <h1>My Todo List</h1>
      <AddTodoForm onAddTodo={handleAddTodo} />
      <TodoList todos={todos} onToggleComplete={handleToggleComplete} />
    </div>
  );
};

export default HomePage;

