import { Todo } from '../types/todo';

const API_BASE_URL = '/api/v1/todos';

// Placeholder for CSRF token retrieval. In a real app, this would fetch from a meta tag,
// a dedicated endpoint, or be managed by a library.
const getCsrfToken = (): string => {
  // For demonstration, returning a dummy token.
  // In production, ensure this is securely generated and retrieved.
  return 'dummy-csrf-token-for-dev';
};

// Utility function for fetch with timeout
const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 10000): Promise<Response> => {
  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeout);
  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    clearTimeout(id);
    return response;
  } catch (error) {
    clearTimeout(id);
    throw error;
  }
};

export const getTodos = async (): Promise<Todo[]> => {
  const response = await fetchWithTimeout(API_BASE_URL);
  if (!response.ok) {
    throw new Error(`Failed to fetch todos: ${response.statusText}`);
  }
  return response.json();
};

export const createTodo = async (title: string): Promise<Todo> => {
  const csrfToken = getCsrfToken();
  const response = await fetchWithTimeout(API_BASE_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrfToken, // Include CSRF token
    },
    body: JSON.stringify({ title }),
  });
  if (!response.ok) {
    throw new Error(`Failed to create todo: ${response.statusText}`);
  }
  return response.json();
};

export const completeTodo = async (id: string): Promise<Todo> => {
  const csrfToken = getCsrfToken();
  const response = await fetchWithTimeout(`${API_BASE_URL}/${id}/complete`, {
    method: 'PUT',
    headers: {
      'X-CSRF-Token': csrfToken, // Include CSRF token
    },
  });
  if (!response.ok) {
    throw new Error(`Failed to complete todo: ${response.statusText}`);
  }
  return response.json();
};

import React, { useEffect, useState, useCallback } from 'react';
import AddTodoForm from '../components/AddTodoForm';
import TodoList from '../components/TodoList';
import { Todo } from '../types/todo';
import { getTodos, createTodo, completeTodo } from '../api/todos';
import './HomePage.css';

const HomePage: React.FC = () => {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchTodos = useCallback(async () => {
    try {
      setLoading(true);
      const data = await getTodos();
      setTodos(data);
    } catch (err) {
      if (err instanceof Error) {
        setError(`Failed to fetch todos: ${err.message}`);
      } else {
        setError('An unexpected error occurred while fetching todos.');
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchTodos();
  }, [fetchTodos]);

  const handleAddTodo = async (title: string) => {
    try {
      const newTodo = await createTodo(title);
      setTodos((prevTodos) => [...prevTodos, newTodo]);
    } catch (err) {
      if (err instanceof Error) {
        setError(`Failed to add todo: ${err.message}`);
      } else {
        setError('An unexpected error occurred while adding a todo.');
      }
    }
  };

  const handleToggleComplete = async (id: string) => {
    try {
      const updatedTodo = await completeTodo(id);
      setTodos((prevTodos) =>
        prevTodos.map((todo) => (todo.id === id ? updatedTodo : todo))
      );
    } catch (err) {
      if (err instanceof Error) {
        setError(`Failed to complete todo: ${err.message}`);
      } else {
        setError('An unexpected error occurred while completing a todo.');
      }
    }
  };

  if (loading) {
    return <div className="homepage-container">Loading todos...</div>;
  }

  if (error) {
    return <div className="homepage-container error-message">Error: {error}</div>;
  }

  return (
    <div className="homepage-container">
      <h1>My Todo List</h1>
      <AddTodoForm onAddTodo={handleAddTodo} />
      <TodoList todos={todos} onToggleComplete={handleToggleComplete} />
    </div>
  );
};

export default HomePage;

