import {
  Repository,
  Commit,
  PullRequest,
  Issue,
  AddRepoRequest,
  AddRepoResponse,
  SyncResponse,
} from '../types/api';

const BASE_URL = '/api/v1'; // Assuming proxy or direct access

interface ApiOptions extends RequestInit {
  apiKey?: string;
}

async function fetchApi<T>(
  path: string,
  options?: ApiOptions
): Promise<T> {
  const headers = {
    'Content-Type': 'application/json',
    ...options?.headers,
  };

  // Add API key if provided (for simple personal use)
  if (options?.apiKey) {
    headers['X-API-Key'] = options.apiKey;
  }

  const response = await fetch(`${BASE_URL}${path}`, {
    ...options,
    headers,
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({ message: 'Unknown error' }));
    throw new Error(errorData.message || `API Error: ${response.statusText}`);
  }

  return response.json();
}

export const apiClient = {
  getRepos: (): Promise<Repository[]> => {
    return fetchApi<Repository[]>('/repos');
  },

  addRepo: (data: AddRepoRequest): Promise<AddRepoResponse> => {
    return fetchApi<AddRepoResponse>('/repos', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  },

  getRepoDetail: (repoId: string): Promise<Repository> => {
    return fetchApi<Repository>(`/repos/${repoId}`);
  },

  deleteRepo: (repoId: string): Promise<{ message: string }> => {
    return fetchApi<{ message: string }>(`/repos/${repoId}`, {
      method: 'DELETE',
    });
  },

  getCommits: (repoId: string): Promise<Commit[]> => {
    return fetchApi<Commit[]>(`/repos/${repoId}/activity/commits`);
  },

  getPulls: (repoId: string): Promise<PullRequest[]> => {
    return fetchApi<PullRequest[]>(`/repos/${repoId}/activity/pulls`);
  },

  getIssues: (repoId: string): Promise<Issue[]> => {
    return fetchApi<Issue[]>(`/repos/${repoId}/activity/issues`);
  },

  triggerSync: (): Promise<SyncResponse> => {
    return fetchApi<SyncResponse>('/sync', {
      method: 'POST',
    });
  },
};

